import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Table from '@mui/joy/Table';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import CircularProgress from '@mui/joy/CircularProgress';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import { ODb } from '../db';

interface StoredQuery {
  name: string;
  query: string;
}

interface PreviewResult {
  count: number;
  samples: { Headline: string; Status: string }[];
  loading: boolean;
}

function QueryPreview({ query }: { query: string }) {
  const [preview, setPreview] = React.useState<PreviewResult>({ count: 0, samples: [], loading: true });
  const [expanded, setExpanded] = React.useState(false);

  React.useEffect(() => {
    if (!query.trim()) {
      setPreview({ count: 0, samples: [], loading: false });
      return;
    }
    const controller = new AbortController();
    setPreview(p => ({ ...p, loading: true }));
    ODb.query(query, false, controller.signal).then(results => {
      if (!controller.signal.aborted) {
        setPreview({
          count: results.length,
          samples: results.slice(0, 5).map(r => ({ Headline: r.Headline, Status: r.Status })),
          loading: false,
        });
      }
    }).catch(() => {
      if (!controller.signal.aborted) {
        setPreview({ count: 0, samples: [], loading: false });
      }
    });
    return () => controller.abort();
  }, [query]);

  if (preview.loading) {
    return <CircularProgress size="sm" />;
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <Chip size="sm" variant="soft" color={preview.count > 0 ? 'primary' : 'neutral'}>
          {preview.count} match{preview.count !== 1 ? 'es' : ''}
        </Chip>
        {preview.samples.length > 0 && (
          <IconButton size="sm" variant="plain" onClick={() => setExpanded(!expanded)}>
            {expanded ? <ExpandLessIcon fontSize="small" /> : <ExpandMoreIcon fontSize="small" />}
          </IconButton>
        )}
      </Box>
      {expanded && preview.samples.length > 0 && (
        <Box sx={{ mt: 0.5, pl: 1 }}>
          {preview.samples.map((s, i) => (
            <Typography key={i} level="body-xs" sx={{ color: 'text.secondary' }}>
              {s.Status && <Chip size="sm" variant="outlined" sx={{ mr: 0.5 }}>{s.Status}</Chip>}
              {s.Headline}
            </Typography>
          ))}
          {preview.count > 5 && (
            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
              ...and {preview.count - 5} more
            </Typography>
          )}
        </Box>
      )}
    </Box>
  );
}

export default function StoredQueries() {
  const [queries, setQueries] = React.useState<StoredQuery[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [newName, setNewName] = React.useState('');
  const [newQuery, setNewQuery] = React.useState('');
  const [saving, setSaving] = React.useState(false);
  const [newQueryPreview, setNewQueryPreview] = React.useState<PreviewResult>({ count: 0, samples: [], loading: false });

  const fetchQueries = React.useCallback(async () => {
    setLoading(true);
    try {
      const result = await ODb.getStoredQueries();
      setQueries(result || []);
    } catch {
      setQueries([]);
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    fetchQueries();
  }, [fetchQueries]);

  // Preview for the new query input (debounced)
  React.useEffect(() => {
    if (!newQuery.trim()) {
      setNewQueryPreview({ count: 0, samples: [], loading: false });
      return;
    }
    const controller = new AbortController();
    const timer = setTimeout(() => {
      setNewQueryPreview(p => ({ ...p, loading: true }));
      ODb.query(newQuery, false, controller.signal).then(results => {
        if (!controller.signal.aborted) {
          setNewQueryPreview({
            count: results.length,
            samples: results.slice(0, 5).map(r => ({ Headline: r.Headline, Status: r.Status })),
            loading: false,
          });
        }
      }).catch(() => {
        if (!controller.signal.aborted) {
          setNewQueryPreview({ count: 0, samples: [], loading: false });
        }
      });
    }, 400);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [newQuery]);

  const handleAdd = async () => {
    if (!newName.trim() || !newQuery.trim()) return;
    setSaving(true);
    try {
      await ODb.saveStoredQuery(newName.trim(), newQuery.trim());
      setNewName('');
      setNewQuery('');
      setNewQueryPreview({ count: 0, samples: [], loading: false });
      await fetchQueries();
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (name: string) => {
    await ODb.deleteStoredQuery(name);
    await fetchQueries();
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      {/* Add new query form */}
      <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2 }}>
        <Typography level="title-md" sx={{ mb: 1.5 }}>Add Query</Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
          <Input
            placeholder="Query name"
            value={newName}
            onChange={e => setNewName(e.target.value)}
            size="sm"
          />
          <Input
            placeholder='Query expression, e.g. IsStatus("TODO") && HasTags("work")'
            value={newQuery}
            onChange={e => setNewQuery(e.target.value)}
            size="sm"
            onKeyDown={e => { if (e.key === 'Enter') handleAdd(); }}
          />
          {newQuery.trim() && (
            <Box sx={{ pl: 1 }}>
              {newQueryPreview.loading ? (
                <CircularProgress size="sm" />
              ) : (
                <Box>
                  <Chip size="sm" variant="soft" color={newQueryPreview.count > 0 ? 'success' : 'neutral'}>
                    {newQueryPreview.count} match{newQueryPreview.count !== 1 ? 'es' : ''}
                  </Chip>
                  {newQueryPreview.samples.length > 0 && (
                    <Box sx={{ mt: 0.5 }}>
                      {newQueryPreview.samples.map((s, i) => (
                        <Typography key={i} level="body-xs" sx={{ color: 'text.secondary' }}>
                          {s.Status && <Chip size="sm" variant="outlined" sx={{ mr: 0.5 }}>{s.Status}</Chip>}
                          {s.Headline}
                        </Typography>
                      ))}
                      {newQueryPreview.count > 5 && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                          ...and {newQueryPreview.count - 5} more
                        </Typography>
                      )}
                    </Box>
                  )}
                </Box>
              )}
            </Box>
          )}
          <Button
            startDecorator={<AddIcon />}
            onClick={handleAdd}
            loading={saving}
            disabled={!newName.trim() || !newQuery.trim()}
            size="sm"
            sx={{ alignSelf: 'flex-start' }}
          >
            Add Query
          </Button>
        </Box>
      </Sheet>

      {/* Existing queries list */}
      <Sheet variant="outlined" sx={{ borderRadius: 'sm', overflow: 'auto' }}>
        {queries.length === 0 ? (
          <Box sx={{ p: 3, textAlign: 'center' }}>
            <Typography level="body-md" sx={{ color: 'text.secondary' }}>
              No stored queries yet. Add one above.
            </Typography>
          </Box>
        ) : (
          <Table stickyHeader hoverRow sx={{ '& tr > *:last-child': { textAlign: 'right' } }}>
            <thead>
              <tr>
                <th style={{ width: '20%' }}>Name</th>
                <th style={{ width: '35%' }}>Query</th>
                <th style={{ width: '35%' }}>Preview</th>
                <th style={{ width: '10%' }}></th>
              </tr>
            </thead>
            <tbody>
              {queries.map(q => (
                <tr key={q.name}>
                  <td>
                    <Typography level="body-sm" fontWeight="md">{q.name}</Typography>
                  </td>
                  <td>
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', wordBreak: 'break-all' }}>
                      {q.query}
                    </Typography>
                  </td>
                  <td>
                    <QueryPreview query={q.query} />
                  </td>
                  <td>
                    <IconButton
                      size="sm"
                      variant="soft"
                      color="danger"
                      onClick={() => handleDelete(q.name)}
                    >
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        )}
      </Sheet>
    </Box>
  );
}
