function pad2(num: number): string {
    return String(num).padStart(2, '0');
}

// A row of an org table. Kind is "data" for a normal row and "sep" for a
// horizontal rule. Advanced carries the org special row marker ("!", "^", "_",
// "$", "/") when the row has one.
export type TableRowData = {
    Kind: string;
    Advanced?: string;
    Cells: string[];
};

// Summary of one table, as listed by /tables.
export type TableInfo = {
    Id: number;
    Filename: string;
    Name: string;
    Heading: string;
    Olp: string[];
    Line: number;
    Rows: number;
    Cols: number;
    Formulas: number;
};

// A table and everything needed to edit it.
export type TableData = TableInfo & {
    EndLine: number;
    Data: TableRowData[];
    FormulaList: string[];
    // Keyed "row,col", both zero based, indexing into Data.
    CellFormulas: Record<string, string>;
    ColNames: Record<string, number> | null;
    Params: Record<string, string> | null;
    Indent: string;
};

export type TableListResult = { Ok: boolean; Msg: string; Tables: TableInfo[] };
export type TableResult = { Ok: boolean; Msg: string; Table: TableData | null };

export type TableEdit = {
    Filename: string;
    Id: number;
    Data: TableRowData[];
    Formulas: string[];
    Name?: string;
    SetName?: boolean;
    Eval?: boolean;
};

